/// What a fixture holds besides the props: each slot's content, and the location it renders at.
#[cfg(test)]
#[derive(serde::Deserialize)]
struct Fixture {
    #[serde(rename = "$slots", default)]
    slots: std::collections::HashMap<String, String>,
    #[serde(rename = "$route", default = "Fixture::root")]
    route: String,
    #[serde(rename = "$stores", default = "Fixture::no_stores")]
    stores: serde_json::Value,
    #[serde(rename = "$locale", default)]
    locale: Option<String>,
    #[serde(rename = "$loads", default)]
    loads: std::collections::HashMap<String, Box<serde_json::value::RawValue>>,
}

#[cfg(test)]
impl Fixture {
    fn root() -> String {
        "/".to_owned()
    }

    fn no_stores() -> serde_json::Value {
        serde_json::Value::Object(Default::default())
    }

    fn slot(&self, name: &str) -> Option<&str> {
        self.slots.get(name).map(String::as_str)
    }
}

/// What was teleported, after a marker, as the conformance suite writes Vue's: `{"target":"…"}`.
#[cfg(test)]
fn teleports_into(out: &mut String, teleports: ferrovue::page::Teleports) {
    let targets = teleports.into_targets();
    if targets.is_empty() {
        return;
    }
    let pairs: Vec<String> = targets
        .iter()
        .map(|(t, html)| format!("{}:{}", serde_json::to_string(t).unwrap(), serde_json::to_string(html).unwrap()))
        .collect();
    out.push_str("<!--fv-teleports-->{");
    out.push_str(&pairs.join(","));
    out.push('}');
}

/// The head, after a marker, as the conformance suite writes unhead's: `{"headTags":"…",…}`.
#[cfg(test)]
fn head_into(out: &mut String, head: &ferrovue::head::Head) {
    let html = head.render();
    if html == ferrovue::head::HeadHtml::default() {
        return;
    }
    let fields = [
        ("headTags", &html.head_tags),
        ("bodyTags", &html.body_tags),
        ("bodyTagsOpen", &html.body_tags_open),
        ("htmlAttrs", &html.html_attrs),
        ("bodyAttrs", &html.body_attrs),
    ];
    let pairs: Vec<String> = fields
        .iter()
        .map(|(k, v)| format!("{}:{}", serde_json::to_string(k).unwrap(), serde_json::to_string(v).unwrap()))
        .collect();
    out.push_str("<!--fv-head-->{");
    out.push_str(&pairs.join(","));
    out.push('}');
}

